export function buildScaffold(p: CatalogProject): Record<string, string> {
  const run =
    p.runtime === "python"
      ? "python -m venv .venv && source .venv/bin/activate && pip install -r requirements.txt\nuvicorn app.main:app --reload   # http://localhost:8000/health"
      : p.runtime === "java"
        ? "mvn spring-boot:run   # http://localhost:8080/actuator/health"
        : "npm install\ncp .env.example .env\nnpm run dev   # http://localhost:3000/health"
  const runtimeFiles = p.runtime === "python" ? pythonFiles() : p.runtime === "java" ? javaFiles() : nodeFiles(p)
  return {
    "README.md": readme(p, run),
    "ARCHITECTURE.md": architecture(p),
    "ROADMAP.md": roadmap(p),
    ...runtimeFiles,
  }
}
